{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "In healthy subjects, pentazocine mean absolute oral bioavailability was 18%, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Loperamide absolute oral bioavailability was 0.3% in humans, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "In patients, estramustine phosphate mean oral bioavailability versus i.v. was 43.7 ± 4.6%, above the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transfer evidence molecules show absolute oral bioavailability below 20% in ordinary conditions, including 18%, 0.3%, 5–17%, and 11 ± 5.2%, supporting low F. One molecule with mean F of 43.7% is contradictory, but the preponderance of direct absolute measurements favors low.",
  "evidence_gaps": [
    "Several records are qualitative ('low', 'poor') rather than numeric absolute F.",
    "Some high-F values come from fed-state or formulation-specific conditions and were discounted.",
    "One molecule consistently shows F >20%, and some molecules have conflicting reported values."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

